import { DataTable } from '@vulcan-ai/vulcan-ui/lib/components/DataTable';
import { hasValue } from '@vulcan-ai/vulcan-ui/lib/helpers/hasValue';
import { styled } from '@vulcan-ai/vulcan-ui/lib/theme';
import React from 'react';
import { FormattedMessage } from 'react-intl';
import { CabinetContributor } from 'src/apps/common/__generated__/types';
import { HeaderCell } from './IAATableCommon';
import { MemberCell } from './MemberCell';
import { ValueCell } from './ValueCell';

interface IAAContentProps {
  memberIds: (string | null)[];
  memberRecord: Record<string, string>;
  indexedRecord: Record<string, number>;
  contributorMap?: Map<string, CabinetContributor>;
  labelingAgentMemberIds: Set<string | null>;
  // Normalized "tmA:tmB" keys of labeler-labeler pairs currently being calculated.
  pendingPairKeys?: Set<string>;
  // Normalized "tmA:tmB" keys of selected pairs that share no labeled documents.
  noOverlapPairKeys?: Set<string>;
}

/** Locale-aware ascending comparator for reliable alphabetical ordering. */
const byLocale = (a: string, b: string): number => a.localeCompare(b);

// memberId is "userId:teamMemberId"; pending keys are sorted teamMemberId pairs.
function pairLoadingKey(a: string | null, b: string | null): string {
  return [a?.split(':')[1] ?? '', b?.split(':')[1] ?? ''].sort(byLocale).join(':');
}

export function IAAContent({
  memberIds,
  memberRecord,
  indexedRecord,
  contributorMap,
  labelingAgentMemberIds,
  pendingPairKeys,
  noOverlapPairKeys,
}: Readonly<IAAContentProps>) {
  return (
    <>
      <DataTable.Head>
        <DataTable.Head.Row />
        <DataTable.Head.Row>
          <HeaderCell stickyTop stickyLeft width={175}>
            <b>
              <FormattedMessage id="common.member" />
            </b>
          </HeaderCell>
          {memberIds.map((memberId) => (
            <MemberCell
              key={memberId}
              variant="header"
              memberId={memberId}
              memberRecord={memberRecord}
              contributorMap={contributorMap}
              stickyTop
              isLabelingAgent={labelingAgentMemberIds.has(memberId)}
            />
          ))}
        </DataTable.Head.Row>
      </DataTable.Head>

      {memberIds.map((horizontalMemberId) => (
        <Row key={`body-${horizontalMemberId}`}>
          <MemberCell
            variant="body"
            memberId={horizontalMemberId}
            memberRecord={memberRecord}
            contributorMap={contributorMap}
            isLabelingAgent={labelingAgentMemberIds.has(horizontalMemberId)}
          />
          {memberIds.map((verticalMemberId) => {
            if (verticalMemberId === horizontalMemberId) {
              return <ValueCell key={verticalMemberId} value={null} />;
            }

            const key1 = [verticalMemberId, horizontalMemberId].join('-');
            const key2 = [horizontalMemberId, verticalMemberId].join('-');
            const value = indexedRecord[key1] ?? indexedRecord[key2];
            const pairKey = pairLoadingKey(horizontalMemberId, verticalMemberId);
            const loading = !hasValue(value) && !!pendingPairKeys?.has(pairKey);
            const noOverlap = !hasValue(value) && !loading && !!noOverlapPairKeys?.has(pairKey);
            return <ValueCell key={verticalMemberId} value={value} loading={loading} noOverlap={noOverlap} />;
          })}
        </Row>
      ))}
    </>
  );
}

const Row = styled(DataTable.Body.Row, { name: 'IAAContent-Row' })(({ theme }) => ({
  borderBottom: `1px solid ${theme.palette.lightGrey2}`,
}));

