import { QueryResult } from '@apollo/client';
import { useErrorIntl } from '@vulcan-ai/frontend-shared/lib/src/commons/error/useErrorIntl';
import { Typography } from '@vulcan-ai/vulcan-ui/lib/components/Typography';
import React, { ReactNode, useEffect, useMemo } from 'react';
import { LoadingCircular } from 'src/app/components/LoadingCircular';
import { GetChartDataQuery, GetChartDataQueryVariables, KeyPayloadType } from 'src/apps/common/__generated__/types';
import { EmptyAnalyticsData } from './EmptyAnalyticsData';

interface Props {
  chartId: string;
  chartDataQueryResult: QueryResult<GetChartDataQuery, GetChartDataQueryVariables>;
  children: (data: GetChartDataQuery, keyPayloadType?: KeyPayloadType) => ReactNode;
  setIsChartEmpty: (isChartEmpty: boolean) => void;
  hasTagFilter?: boolean;
}

export function ChartDataQueryHandler({
  chartId,
  chartDataQueryResult,
  children,
  setIsChartEmpty,
  hasTagFilter,
}: Props) {
  const formatError = useErrorIntl();

  const numberOfDataPoint = useMemo(() => {
    let result = 0;
    chartDataQueryResult.data?.result.forEach((row) => {
      row.values.forEach((v) => (result += parseFloat(v.value)));
    });

    return result;
  }, [chartDataQueryResult.data]);

  const keyPayloadType = useMemo(() => {
    for (const row of chartDataQueryResult.data?.result ?? []) {
      if (row.keyPayloadType) {
        return row.keyPayloadType;
      }
    }
    return undefined;
  }, [chartDataQueryResult.data]);

  useEffect(() => {
    if (chartDataQueryResult.loading) {
      return setIsChartEmpty(false);
    }
    if (chartDataQueryResult.error) {
      return setIsChartEmpty(false);
    }
    if (chartDataQueryResult.data && numberOfDataPoint > 0) {
      return setIsChartEmpty(false);
    }
    return setIsChartEmpty(true);
  }, [chartDataQueryResult.data, chartDataQueryResult.loading, chartDataQueryResult.error, numberOfDataPoint]);

  if (chartDataQueryResult.loading) {
    return <LoadingCircular />;
  }

  if (chartDataQueryResult.error) {
    return <Typography variant="body1">{formatError(chartDataQueryResult.error)}</Typography>;
  }

  if (chartDataQueryResult.data && numberOfDataPoint > 0) {
    return <>{children(chartDataQueryResult.data, keyPayloadType)}</>;
  }

  return <EmptyAnalyticsData chartId={chartId} hasTagFilter={hasTagFilter} />;
}

